from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Find the full-length 2 divider.  The 8 stripe is parallel to it.
    div = None
    vertical = False
    for c in range(w):
        if all(grid[r][c] == 2 for r in range(h)):
            div, vertical = c, True
            break
    if div is None:
        for r in range(h):
            if all(grid[r][c] == 2 for c in range(w)):
                div, vertical = r, False
                break
    if div is None:
        return out
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (bg,2)]
    if not pts:
        return out
    if vertical:
        cols = [c for r,c in pts]
        # If the foreground abuts the divider, mark just beyond its far edge.
        if min(abs(c-div) for c in cols) == 1:
            target = min(cols)-1 if max(cols) < div else max(cols)+1
        else:
            # Use the leading component of the figure's first occupied row.
            top = min(r for r,c in pts)
            firstrow = sorted(c for r,c in pts if r == top)
            if len(set(r for r,c in pts)) == 1:
                target = firstrow[0]
            elif len(firstrow) == 1:
                target = (div + 1) // 2
            else:
                # right edge of the leftmost contiguous run in that row
                run = [firstrow[0]]
                for c in firstrow[1:]:
                    if c == run[-1] + 1:
                        run.append(c)
                    else:
                        break
                target = run[-1]
        if 0 <= target < w:
            for r in range(h): out[r][target] = 8
    else:
        rows = [r for r,c in pts]
        distinct_rows = sorted(set(rows))
        # A single horizontal bar points toward the divider; put the stripe
        # immediately beyond that bar. Otherwise mark the object's edge nearest
        # the divider (single-pixel markers remain on their own row).
        if len(distinct_rows) == 1 and len(pts) > 1 and abs(distinct_rows[0] - div) >= 3:
            r0 = distinct_rows[0]
            target = r0 + 1 if r0 < div else r0 - 1
        else:
            target = max(rows) if max(rows) < div else min(rows)
        if 0 <= target < h:
            for c in range(w): out[target][c] = 8
    return out
